package com.rtsbuilding.rtsbuilding.server.service.page;
import com.rtsbuilding.rtsbuilding.Config; import com.rtsbuilding.rtsbuilding.network.storage.C2SRtsRequestStoragePagePayload; import com.rtsbuilding.rtsbuilding.network.storage.RtsStorageSort; import com.rtsbuilding.rtsbuilding.server.storage.session.RtsStorageSession; import com.rtsbuilding.rtsbuilding.util.RtsPinyinSearch;
import net.minecraft.entity.player.EntityPlayerMP; import net.minecraft.util.ResourceLocation; import net.minecraftforge.fml.common.registry.ForgeRegistries;
import java.util.*;
public final class RtsPageSharedHelpers {
 static final int PLAYER_MAIN_INVENTORY_END_EXCLUSIVE=36; static final String CATEGORY_ALL="all",CATEGORY_MOD_PREFIX="mod|",CATEGORY_TAB_PREFIX="tab|";
 private RtsPageSharedHelpers(){}
 public static int defaultPageSize(){return Config.defaultStoragePageSize();} public static int maxPageSize(){return Config.maxStoragePageSize();} public static int sanitizePageSize(int p){return Math.max(1,Math.min(maxPageSize(),p));}
 static boolean matchesSearchQuery(ResourceLocation id,String rawId,String label,String query,boolean pinyin,Set<String>localized){if(query==null||query.isEmpty())return true;String raw=rawId==null?"":rawId.toLowerCase(Locale.ROOT);if(localized!=null&&localized.contains(raw))return true;if(query.startsWith("@")){String q=query.substring(1).trim();return q.isEmpty()||(id!=null&&id.getNamespace().toLowerCase(Locale.ROOT).contains(q));}String name=label==null?"":label.toLowerCase(Locale.ROOT);return raw.contains(query)||name.contains(query)||(pinyin&&RtsPinyinSearch.contains(label,query));}
 public static Set<String> sanitizeLocalizedSearchMatches(List<String> values){if(values==null)return Collections.emptySet();Set<String> out=new HashSet<String>();for(String value:values){ResourceLocation id=parse(value);if(id==null||!ForgeRegistries.ITEMS.containsKey(id))continue;out.add(id.toString());if(out.size()>=C2SRtsRequestStoragePagePayload.MAX_LOCALIZED_SEARCH_MATCHES)break;}return out;}
 static Comparator<Entry> entryComparator(RtsStorageSort sort,boolean asc){Comparator<Entry> c;if(sort==RtsStorageSort.MOD)c=new Comparator<Entry>(){public int compare(Entry a,Entry b){int x=ci(a.namespace(),b.namespace());if(x==0)x=ci(a.label(),b.label());if(x==0)x=ci(a.path(),b.path());if(x==0)x=exactStackTie(a,b);return x;}};else if(sort==RtsStorageSort.NAME)c=new Comparator<Entry>(){public int compare(Entry a,Entry b){int x=ci(a.label(),b.label());if(x==0)x=ci(a.namespace(),b.namespace());if(x==0)x=ci(a.path(),b.path());if(x==0)x=exactStackTie(a,b);return x;}};else c=new Comparator<Entry>(){public int compare(Entry a,Entry b){int x=Long.compare(a.count(),b.count());if(x==0)x=ci(a.label(),b.label());if(x==0)x=ci(a.itemId(),b.itemId());if(x==0)x=exactStackTie(a,b);return x;}};return asc?c:Collections.reverseOrder(c);}
 /** 同名同 ID 变体用 metadata/NBT 作最终稳定键，避免翻页时顺序漂移。 */
 private static int exactStackTie(Entry a,Entry b){int x=Integer.compare(a.stack().getMetadata(),b.stack().getMetadata());if(x!=0)return x;String at=a.stack().hasTagCompound()?a.stack().getTagCompound().toString():"";String bt=b.stack().hasTagCompound()?b.stack().getTagCompound().toString():"";return at.compareTo(bt);}
 static Comparator<FluidEntry> fluidComparator(RtsStorageSort sort,boolean asc){Comparator<FluidEntry> c;if(sort==RtsStorageSort.MOD)c=new Comparator<FluidEntry>(){public int compare(FluidEntry a,FluidEntry b){int x=ci(a.namespace(),b.namespace());return x!=0?x:ci(a.path(),b.path());}};else if(sort==RtsStorageSort.NAME)c=new Comparator<FluidEntry>(){public int compare(FluidEntry a,FluidEntry b){int x=ci(a.path(),b.path());return x!=0?x:ci(a.namespace(),b.namespace());}};else c=new Comparator<FluidEntry>(){public int compare(FluidEntry a,FluidEntry b){int x=Long.compare(a.amount(),b.amount());return x!=0?x:ci(a.fluidId(),b.fluidId());}};return asc?c:Collections.reverseOrder(c);}
 private static int ci(String a,String b){return String.CASE_INSENSITIVE_ORDER.compare(a==null?"":a,b==null?"":b);}
 static int compareNamespace(String a,String b){if("minecraft".equals(a))return"minecraft".equals(b)?0:-1;if("minecraft".equals(b))return 1;return ci(a,b);} static int compareTabKey(String a,String b){ResourceLocation x=parse(a),y=parse(b);String xn=x==null?a:x.getPath(),yn=y==null?b:y.getPath();int c=ci(xn,yn);return c!=0?c:ci(a,b);}
 static String encodeModCategory(String ns){return CATEGORY_MOD_PREFIX+ns;} static String encodeTabCategory(String ns,String tab){return CATEGORY_TAB_PREFIX+ns+"|"+tab;}
 public static String normalizeCategory(String c){if(c==null)return CATEGORY_ALL;String v=c.toLowerCase(Locale.ROOT).trim();if(v.isEmpty()||CATEGORY_ALL.equals(v))return CATEGORY_ALL;if(v.startsWith(CATEGORY_MOD_PREFIX)||v.startsWith(CATEGORY_TAB_PREFIX))return v;return encodeModCategory(v);}
 static CategorySelection parseCategorySelection(String c){if(c==null||CATEGORY_ALL.equals(c))return CategorySelection.all();if(c.startsWith(CATEGORY_MOD_PREFIX)){String n=c.substring(CATEGORY_MOD_PREFIX.length());return n.trim().isEmpty()?CategorySelection.all():CategorySelection.mod(n);}if(c.startsWith(CATEGORY_TAB_PREFIX)){String p=c.substring(CATEGORY_TAB_PREFIX.length());int i=p.indexOf('|');if(i<=0||i>=p.length()-1)return CategorySelection.all();String n=p.substring(0,i),t=p.substring(i+1);return n.trim().isEmpty()||t.trim().isEmpty()?CategorySelection.all():CategorySelection.tab(n,t);}return CategorySelection.all();}
 static boolean isValidCategorySelection(CategorySelection s,List<String>categories){if(s==null||s.type()==CategorySelectionType.ALL)return true;String token=s.type()==CategorySelectionType.MOD?encodeModCategory(s.namespace()):encodeTabCategory(s.namespace(),s.tabKey());return categories!=null&&categories.contains(token);}
 public static int getPlayerMainInventoryStart(EntityPlayerMP p){return 0;} public static int getPlayerMainInventoryEndExclusive(EntityPlayerMP p){return p==null?0:Math.min(PLAYER_MAIN_INVENTORY_END_EXCLUSIVE,p.inventory.getSizeInventory());}
 public static boolean shouldIncludePlayerMainInventoryInStorageView(EntityPlayerMP player,RtsStorageSession session){if(player==null||player.openContainer instanceof com.rtsbuilding.rtsbuilding.server.menu.RtsCraftTerminalMenu)return false;if(session!=null&&session.linkedStorageInfo.isEmpty()&&!com.rtsbuilding.rtsbuilding.compat.bd.RtsBdCompat.hasPrimaryNetwork(player))return true;return player.openContainer==player.inventoryContainer;}
 static ResourceLocation parse(String value){if(value==null||value.trim().isEmpty())return null;try{return new ResourceLocation(value);}catch(RuntimeException e){return null;}}
}
